<?php
    class CreateCategoryHandler extends Handler {
        public function handle($input) {
            global $processorProvider;

            $response = NULL;
            if (array_key_exists("includedRegions", $input)) {
                $response = $processorProvider->run("AddCompositeRegion", $input);
            }
            else if (array_key_exists("latitude", $input) && array_key_exists("longitude", $input)) {
                $response = $processorProvider->run("AddGeographicalRegionExtension", $input);
            }
            else {
                $response = $processorProvider->run("AddGeographicalRegion", $input);
            }
    
            return $this->createResponse(201, $response);
        }

        public function getTag() {
            return "Categories";
        }

        public function getPath() {
            return "/categories";
        }

        public function getParameters() {
            return array();
        }

        public function getMethod() {
            return "POST";
        }

        public function getOperationId() {
            return "create_category";
        }
        
        public function getShortDescription() {
            return "Create a category";
        }
        
        public function getLongDescription() {
            global $databaseProvider;
            $allowedCategories = explode(",", str_replace("'", "`", substr($databaseProvider
                ->statementBuilder("SELECT column_type FROM information_schema.COLUMNS WHERE TABLE_NAME = 'category_identifier' AND COLUMN_NAME = 'category'")
                ->getSingleColumn("column_type"), 5, -1)));

            return "Creates a category. This also initiates an update of categories for all places, which means that the category will be contained in all related places categories, after the update is done (which can take some time). The allowed category categories are: " . implode(", ", $allowedCategories);
        }
        
